\draw[<->,line width=0.5pt] (0,-10.5)--(0,10.5) node[above,font=\fontsize{10}{12}\selectfont] {$y$};
\foreach \v in {-4,-3,-2,-1,1,2,3,4}{\draw[line width=0.4pt] (\v,-0.12)--(\v,0.12);\node[below,font=\fontsize{8.5}{10}\selectfont] at (\v,-0.12) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
